import fs from 'node:fs/promises';
import WebSocket from '/usr/local/lib/node_modules/@deepseek-ai/dsh/node_modules/ws/index.js';

const b64u = (b) => Buffer.from(b).toString('base64').replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '');
const y = await fs.readFile(process.env.HOME + '/.dsh/.credentials.yaml', 'utf8');
const m = y.match(/client-connection\/browser-session:[\s\S]*?secret:\s*([A-Za-z0-9_-]+)/);
const s = Buffer.from(m[1].replaceAll('-', '+').replaceAll('_', '/') + '='.repeat((4 - (m[1].length % 4)) % 4), 'base64');
const a = '127.0.0.1:3080';
const name = 'dsh-auth-' + b64u(createHash('sha256').update(a).digest());
const t = Date.now();
const body = b64u(Buffer.from(JSON.stringify({ version: 1, authority: a, issuedAt: t, expiresAt: t + 12 * 3600 * 1000 }), 'utf8'));
const cookie = `${name}=v1.${body}.${b64u(createHmac('sha256', s).update(body).digest())}`;

const ws = new WebSocket('ws://127.0.0.1:3080/api/remote.mux', { headers: { cookie } });
const streams = new Map();

function open(endpoint, args = {}, onItem, max = 3) {
  const streamId = randomUUID();
  streams.set(streamId, { endpoint, onItem, count: 0, max });
  ws.send(JSON.stringify({ type: 'open', streamId, endpoint, payload: { args } }));
}

