  const frame = JSON.parse(data.toString());
  const st = streams.get(frame.streamId);
  if (!st) return;
  if (frame.type === 'error') {
    console.log(`[${st.endpoint}] ERROR`, JSON.stringify(frame.error));
    return;
  }
  if (frame.type === 'end') {
    console.log(`[${st.endpoint}] END`);
    return;
  }
  st.count += 1;
  if (st.count <= st.max) st.onItem(frame.value);
});

ws.on('error', (e) => console.log('socket error', e.message));
setTimeout(() => { ws.close(); process.exit(0); }, 6000);
